test('Concurrent final rate slot admits one request and rejects the other',function()use(&$clock,$argv,&$r){$clock+=120;for($i=0;$i<59;$i++)status(request(),200);$workers=[];for($i=0;$i<2;$i++){$pipes=[];$proc=proc_open([PHP_BINARY,__FILE__,$argv[1],$argv[2],$argv[3],'worker',(string)$clock],[0=>['pipe','r'],1=>['pipe','w'],2=>['pipe','w']],$pipes);ok(is_resource($proc));fclose($pipes[0]);$workers[]=[$proc,$pipes];}$codes=[];foreach($workers as[$proc,$pipes]){$o=stream_get_contents($pipes[1]);$e=stream_get_contents($pipes[2]);fclose($pipes[1]);fclose($pipes[2]);ok(proc_close($proc)===0&&$e==='');$codes[]=(int)$o;}sort($codes);ok($codes===[200,429]);$clock+=61;});
